flow('Compare: Compare with lists only drives near this one; two near drives on different roads say they share no road; a drive alone says so (free roamer B, 2026-11-14)', async (page, base) => {
  await page.addInitScript(() => { try { localStorage.setItem('apex.onboarded', '1'); } catch (_) {} });
  await page.goto(base + '/analysis.html');
  await page.waitForFunction(() => window.apexLogDebug && window.apexLogDebug.loaded() && window.ApexRecording);
  // the same profile 2 km apart (seed 0 and 1: boxes overlap, nothing of one road lies on the other), and once 100 km away (seed 50)
  await page.evaluate(async (src) => { const gen = eval(src);
    for (const [k, seed, name] of [[0, 0, 'Dry Ridge Rd'], [1, 1, 'Pebble Ridge'], [2, 50, 'Far Hollow Rd']])
      await ApexRecording.store(ApexRecording.parse(ApexCore, gen('saw', seed), 'X' + k + '.csv', { id: 'X' + k, name, date: `2026-0${7 + k}-01T09:00`, source: 'web-gps' })); }, PROFILE_CSV);
  const look = async (a) => {
    await page.goto(base + '/analysis.html?tab=compare');
    await page.waitForFunction(() => window.apexLogDebug && window.apexLogDebug.loaded() && document.querySelector('#cards').textContent.trim(), null, { timeout: 20000 });
    if (a) { await page.evaluate((id) => { const s = document.getElementById('selA'); s.value = id; s.dispatchEvent(new Event('change')); }, a);
      await page.waitForFunction(() => /share|Shared|No other/.test(document.querySelector('#cards').textContent), null, { timeout: 20000 }); }
    return page.evaluate(() => ({ cards: document.getElementById('cards').textContent.trim(), road: document.getElementById('cmpRoad').hidden,
      corners: document.getElementById('cmpCorners').hidden, pick: document.querySelector('.compare-pick').hidden,
      a: document.getElementById('selA').value, with: [...document.getElementById('selB').options].map((o) => o.value),
      withShown: !document.getElementById('selB').closest('label').hidden, swap: !document.getElementById('swapBtn').hidden }));
  };
  const near = await look('X0');
  check(JSON.stringify(near.with) === '["X1"]' && near.withShown && near.swap, 'Compare with: only the near drive, not the one 100 km away: ' + JSON.stringify(near));
  check(/share no road/.test(near.cards) && near.road && near.corners && !near.pick, 'near, different roads: one line, the pickers stay, nothing empty under it: ' + JSON.stringify(near));
  const alone = await look('X2');
  check(/No other drive on this road yet/.test(alone.cards) && !alone.with.length && !alone.withShown && !alone.swap && !alone.pick && alone.road && alone.corners,
    'a drive alone: one line, this drive\'s picker stays, no empty Compare with or Swap: ' + JSON.stringify(alone));
});

flow('the drive page\'s map: with no map to be had the picture keeps its blank panel; MapLibre loads only for it (TestFlight 15)', async (page, base) => {
  await page.addInitScript(() => { try { localStorage.setItem('apex.onboarded', '1'); } catch (_) {} });
  await page.goto(base + '/analysis.html');
  await page.waitForFunction(() => window.apexLogDebug && window.apexLogDebug.loaded() && window.ApexRecording);
  await storeDashDrive(page, 'bm1', 'Map road');
  check(!(await page.evaluate(() => !!window.maplibregl || performance.getEntriesByType('resource').some((e) => /maplibre-gl\.js/.test(e.name)))),
    'the Log list never loads MapLibre');
  await page.goto(base + '/analysis.html?drive=bm1');
  await page.waitForSelector('.dv-plan svg');
  await page.evaluate(() => document.querySelector('.dv-plan').scrollIntoView());
  // tiles are blocked here: MapLibre loads for the picture, its style fails, and the map is taken away again
  await page.waitForFunction(() => !!window.maplibregl, null, { timeout: 15000 });
  await page.waitForFunction(() => !document.querySelector('.dv-basemap'), null, { timeout: 15000 });
  const s = await page.evaluate(() => ({ on: document.querySelector('.dv-plan').classList.contains('on-map'), credit: document.querySelector('.dv-credit').hidden,
    path: document.querySelectorAll('#dvSpeed line').length, casing: !!document.querySelector('#dvCase'),
    note: (document.querySelector('.dv-plan .dv-mapnote') || {}).textContent, key: !!document.querySelector('.dv-recenter') }));
  check(!s.on && s.credit && s.path > 10 && s.casing && !s.key, 'the blank panel, the path drawn, no credit for a map not shown: ' + JSON.stringify(s));
  check(s.note === 'Map couldn’t load', 'never silent: the panel says the map couldn’t load: ' + JSON.stringify(s.note));

  // a corner row zooms the plain picture in on that corner too; a tap on the picture off the marks shows the whole drive
  const p = await page.evaluate(() => {
    document.querySelector('.dv-corner').click();
    const zoomed = document.querySelector('#dvGeo').getAttribute('transform');
    document.querySelector('.dv-plan svg').dispatchEvent(new MouseEvent('click', { bubbles: true }));
    return { zoomed, back: document.querySelector('#dvGeo').getAttribute('transform') };
  });
  const sc = /^matrix\(([\d.]+) /.exec(p.zoomed || '');
  check(sc && +sc[1] > 2 && p.back == null, 'the plain picture zooms to the corner and back: ' + JSON.stringify(p));
});

flow('the main map: with no signal and no saved area one line says there is no map and what still works, gone when a tile draws (no silent blank)', async (page, base) => {
  await page.addInitScript(() => { try { localStorage.setItem('apex.onboarded', '1'); localStorage.setItem('apex.permsExplained', '1'); } catch (_) {}
    Object.defineProperty(Navigator.prototype, 'onLine', { get: () => !window.__off, configurable: true }); window.__off = true; });
  let tiles = false;   // no style, no tiles: every request off the app refused, as the default; then the map's server answers
  await page.route('https://tiles.openfreemap.org/**', (route) => (!tiles ? route.abort('internetdisconnected') : route.request().url().includes('/styles/')
    ? route.fulfill({ contentType: 'application/json', body: JSON.stringify({ version: 8, sources: { openmaptiles: { type: 'vector', tiles: ['https://tiles.openfreemap.org/t/{z}/{x}/{y}.pbf'], maxzoom: 14 } },
      layers: [{ id: 'bg', type: 'background', paint: { 'background-color': '#eee' } }, { id: 'water', type: 'fill', source: 'openmaptiles', 'source-layer': 'water' }] }) })
    : route.fulfill({ status: 200, contentType: 'application/x-protobuf', body: Buffer.alloc(0) })));
  await page.goto(base + '/index.html');
  await page.waitForFunction(() => window.apexDebug && window.apexDebug.map);
  await page.waitForFunction(() => !document.getElementById('mapNote').hidden, null, { timeout: 8000 });
  const off = await page.evaluate(() => { const n = document.getElementById('mapNote'), r = n.getBoundingClientRect(), m = document.getElementById('map').getBoundingClientRect();
    return { text: n.textContent, inside: r.left >= m.left && r.right <= m.right && r.top >= m.top, taps: getComputedStyle(n).pointerEvents }; });
  check(off.text === 'No map here without signal. Notes and recording still work.' && off.inside && off.taps === 'none', 'said in one line, over the map, never in the way: ' + JSON.stringify(off));
  // a first launch with no style kept: the map still loads on the paper, so the route, the trail and the corners can draw
  await page.waitForFunction(() => { try { return !!window.apexDebug.map.getLayer('apex-route'); } catch (_) { return false; } }, null, { timeout: 8000 });
  check(true, 'our own layers are on the paper with no base map');
  // a tile that draws (a saved area here, or the signal back) takes it away
  tiles = true;
  await page.evaluate(() => window.apexDebug.map.setStyle('https://tiles.openfreemap.org/styles/liberty?again'));
  await page.waitForTimeout(2500);
  check(await page.evaluate(() => document.getElementById('mapNote').hidden), 'no note once the map draws');
});

