for (const [when, iso, expect] of [['at dusk', '2026-06-21T00:30:00Z', 1], ['at noon', '2026-06-21T17:00:00Z', 0]]) {
  flow(`a mapped deer crossing ${when}: called in cruise from dusk to dawn, left to the notes by day (road_marks.js cruiseWorthy)`, async (page, base) => {
    await page.clock.setFixedTime(new Date(iso));
    await page.addInitScript(() => { try { localStorage.setItem('apex.onboarded', '1'); } catch (_) {}
      window.__said = []; window.APEX_REVIEW = true;
      window.webkit = { messageHandlers: { apex: { postMessage(m) { if (m && m.cmd === 'said') window.__said.push(m.text); } } } }; });
    await page.goto(base + '/index.html');
    await page.waitForFunction(() => window.apexDebug && window.apexDebug.map && window.apex && window.apex.live && window.ApexRoadMarks);
    const lat = (m) => 35.5 + m / 110540, gpx = [];
    for (let m = 0; m <= 2500; m += 5) gpx.push(`<trkpt lat="${lat(m).toFixed(7)}" lon="-83.9"/>`);
    await page.setInputFiles('#gpxFile', { name: 'deer.gpx', mimeType: 'application/gpx+xml', buffer: Buffer.from(`<gpx><trk><name>Deer Run</name><trkseg>${gpx.join('')}</trkseg></trk></gpx>`) });
    await page.waitForFunction(() => window.apexDebug.track && window.apexDebug.track.name === 'Deer Run', null, { timeout: 10000 });
    await page.evaluate(() => { const t = apexDebug.track, i = t.dist.findIndex((d) => d >= 1200);
      t.marks = [{ type: 'mark', kind: 'animal_crossing', code: 'ANIMAL', call: 'Deer crossing', index: i, dist_m: t.dist[i], lat: t.lat[i], lon: t.lon[i] }]; });
    await page.evaluate(() => window.apex.onNative({ type: 'carplay', action: 'start' }));
    await page.waitForFunction(() => window.apexDebug.driveActive);
    check(await page.evaluate(() => apexDebug.state.notesMode) !== 'full', 'notes on Auto (cruise on a straight road)');
    const iAt = (m) => page.evaluate((m) => apexDebug.track.dist.findIndex((d) => d >= m), m);
    for (let i = await iAt(700), end = await iAt(1190); i <= end; i += 4) {
      await page.evaluate(([i]) => { const t = apexDebug.track;
        window.apex.live({ lat: t.lat[i], lon: t.lon[i], accuracy_m: 5, speed_mps: 20, course_deg: 0, has_fix: true, lat_g: 0, lon_g: 0, calibration: 'locked', thermal: 0 }); }, [i]);
      await page.waitForTimeout(40);
    }
    // the call's lead at 20 m/s is the last few fixes: the page may take a moment to read them and speak, so give it 2 s
    // (each fix the same, at 20 m before the sign) before deciding
    const deer = () => page.evaluate(() => window.__said.filter((s) => /Deer crossing/.test(s)).length);
    for (let k = 0; k < 20 && (await deer()) < 1; k++) { await page.evaluate(([i]) => { const t = apexDebug.track;
      window.apex.live({ lat: t.lat[i], lon: t.lon[i], accuracy_m: 5, speed_mps: 20, course_deg: 0, has_fix: true, lat_g: 0, lon_g: 0, calibration: 'locked', thermal: 0 }); }, [await iAt(1180)]);
      await page.waitForTimeout(100); }
    const said = await page.evaluate(() => window.__said.filter((s) => /Deer crossing/.test(s)));
    check(said.length === expect, `${when}: ${JSON.stringify(await page.evaluate(() => window.__said))}`);
  });
}

flow('the co-driver says a speed limit that drops ahead once, before the sign, early enough to slow (limit_ahead.js)', async (page, base) => {
  await page.addInitScript(() => { try { localStorage.setItem('apex.onboarded', '1'); } catch (_) {}
    window.__said = []; window.APEX_REVIEW = true;
    window.webkit = { messageHandlers: { apex: { postMessage(m) { if (m && m.cmd === 'said') window.__said.push(m.text); } } } }; });
  await page.goto(base + '/index.html');
  await page.waitForFunction(() => window.apexDebug && window.apexDebug.map && window.apex && window.apex.live && window.ApexLimitAhead);
  // a straight road north, 3 km: 55 mph, then 35 mph from 1.5 km (into a town)
  const lat = (m) => 35.5 + m / 110540, LON = -83.9, gpx = [];
  for (let m = 0; m <= 3000; m += 5) gpx.push(`<trkpt lat="${lat(m).toFixed(7)}" lon="${LON.toFixed(7)}"/>`);
  await page.setInputFiles('#gpxFile', { name: 'town.gpx', mimeType: 'application/gpx+xml', buffer: Buffer.from(`<gpx><trk><name>Into town</name><trkseg>${gpx.join('')}</trkseg></trk></gpx>`) });
  await page.waitForFunction(() => window.apexDebug.track && window.apexDebug.track.name === 'Into town', null, { timeout: 10000 });
  await page.evaluate(() => window.apex.onNative({ type: 'carplay', action: 'start' }));
  await page.waitForFunction(() => window.apexDebug.driveActive);
  await page.evaluate(() => { const t = apexDebug.track; t.limitMps = t.dist.map((d) => (d < 1500 ? 55 : 35) * 0.44704); });
  const iAt = (m) => page.evaluate((m) => apexDebug.track.dist.findIndex((d) => d >= m), m);
  const said = () => page.evaluate(() => window.__said.filter((s) => /^Limit /.test(s)));
  let whenM = null;
  for (let i = await iAt(900), end = await iAt(1490); i <= end; i += 4) {
    await page.evaluate(([i]) => { const t = apexDebug.track;
      window.apex.live({ lat: t.lat[i], lon: t.lon[i], accuracy_m: 5, speed_mps: 25, course_deg: 0, has_fix: true, lat_g: 0, lon_g: 0, calibration: 'locked', thermal: 0 }); }, [i]);
    await page.waitForTimeout(40);
    if (whenM == null && (await said()).length) whenM = await page.evaluate(() => apexDebug.state.cursorM);
  }
  check(JSON.stringify(await said()) === '["Limit 35 ahead."]', 'said once: ' + JSON.stringify(await page.evaluate(() => window.__said)));
  // at 25 m/s: 75 m to hear it plus an easy slowing to 35 mph, about 200 m before the sign; not a kilometre early
  check(whenM != null && whenM >= 1500 - 260 && whenM <= 1500 - 120, 'said about 200 m before the sign, at ' + whenM);
  for (let i = await iAt(1500), end = await iAt(1800); i <= end; i += 4) {
    await page.evaluate(([i]) => { const t = apexDebug.track;
      window.apex.live({ lat: t.lat[i], lon: t.lon[i], accuracy_m: 5, speed_mps: 16, course_deg: 0, has_fix: true, lat_g: 0, lon_g: 0, calibration: 'locked', thermal: 0 }); }, [i]);
    await page.waitForTimeout(20);
  }
  check((await said()).length === 1, 'not again in town: ' + JSON.stringify(await said()));
});

flow('road marks: a stop sign and a railway crossing from the map are pinned on the route and called with the notes, the stop early enough to brake (road_marks.js)', async (page, base) => {
  await page.addInitScript(() => { try { localStorage.setItem('apex.onboarded', '1'); localStorage.setItem('apex.prefs', JSON.stringify({ notesMode: 'full', nightMode: 'off' })); } catch (_) {}
    window.__said = []; window.APEX_REVIEW = true;
    window.webkit = { messageHandlers: { apex: { postMessage(m) { if (m && m.cmd === 'said') window.__said.push(m.text); } } } }; });
  // a straight road north, 3 km; the map has a stop sign at 1.5 km (the route is the minor road at a junction) and a level crossing at 2.2 km
  const KY = 110540, lat = (m) => 35.5 + m / KY, LON = -83.9, kx = 111320 * Math.cos(35.5 * Math.PI / 180);
  const g = (m, dx = 0) => ({ lat: lat(m), lon: LON + dx / kx });
  const ids = []; for (let m = 0; m <= 3000; m += 100) ids.push(1000 + m / 100);
  const elements = [
    { type: 'way', id: 1, tags: { highway: 'tertiary', name: 'Straight Road' }, nodes: ids, geometry: ids.map((_, k) => g(k * 100)) },
    { type: 'way', id: 2, tags: { highway: 'primary', name: 'Big Pike' }, nodes: [9001, 1015, 9002], geometry: [g(1500, -300), g(1500), g(1500, 300)] },
    { type: 'node', id: 1015, ...g(1500), tags: { highway: 'stop' } },
    { type: 'node', id: 1022, ...g(2200), tags: { railway: 'level_crossing' } },
  ];
  for (const host of ['overpass-api.de', 'overpass.kumi.systems', 'overpass.private.coffee', 'maps.mail.ru'])
    await page.route(`https://${host}/**`, (route) => route.fulfill({ contentType: 'application/json', body: JSON.stringify({ elements }) }));
  await page.goto(base + '/index.html');
  await page.waitForFunction(() => window.apexDebug && window.apexDebug.map && window.apex && window.apex.live && window.ApexRoadMarks);
  const gpx = []; for (let m = 0; m <= 3000; m += 5) gpx.push(`<trkpt lat="${lat(m).toFixed(7)}" lon="${LON.toFixed(7)}"/>`);
  await page.setInputFiles('#gpxFile', { name: 'straight.gpx', mimeType: 'application/gpx+xml', buffer: Buffer.from(`<gpx><trk><name>Straight Road</name><trkseg>${gpx.join('')}</trkseg></trk></gpx>`) });
  await page.waitForFunction(() => window.apexDebug.track && window.apexDebug.track.name === 'Straight Road', null, { timeout: 10000 });
  await page.waitForFunction(() => Array.isArray(apexDebug.track.marks) && apexDebug.track.marks.length, null, { timeout: 30000 })   // the map's answer lands after the plan: asked again
    .catch(async () => { throw new Error('no marks: ' + JSON.stringify(await page.evaluate(() => apexDebug.lastCtx))); });
  const marks = await page.evaluate(() => apexDebug.track.marks.map((m) => [m.code, Math.round(m.dist_m)]));
  check(marks.length === 2 && marks[0][0] === 'STOP' && Math.abs(marks[0][1] - 1500) <= 30 && marks[1][0] === 'RAIL' && Math.abs(marks[1][1] - 2200) <= 30, 'the stop and the crossing on the route: ' + JSON.stringify(marks));
  check(await page.evaluate(() => [...document.querySelectorAll('.pin.mark')].map((p) => p.textContent).join(',')) === 'STOP,RAIL', 'pinned on the map');
  await page.evaluate(() => window.apex.onNative({ type: 'carplay', action: 'start' }));
  await page.waitForFunction(() => window.apexDebug.driveActive);
  const at = (i, v) => page.evaluate(([i, v]) => { const t = apexDebug.track;
    window.apex.live({ lat: t.lat[i], lon: t.lon[i], accuracy_m: 5, speed_mps: v, course_deg: 0, has_fix: true, lat_g: 0, lon_g: 0, calibration: 'locked', thermal: 0 }); }, [i, v]);
  const iAt = (m) => page.evaluate((m) => apexDebug.track.dist.findIndex((d) => d >= m), m);
  let saidAt = null;
  for (let i = await iAt(1000), end = await iAt(1490); i <= end && saidAt === null; i += 2) {
    await at(i, 25); await page.waitForTimeout(40);
    if (await page.evaluate(() => window.__said.some((s) => /^Stop sign/.test(s)))) saidAt = await page.evaluate((i) => apexDebug.track.dist[i], i);
  }
  check(saidAt !== null && 1500 - saidAt >= 92, `"Stop sign" said with room to stop from 25 m/s (${saidAt === null ? 'never' : Math.round(1500 - saidAt) + ' m before'}): ` + JSON.stringify(await page.evaluate(() => window.__said)));
  for (let i = await iAt(1500), end = await iAt(2190); i <= end; i += 3) { await at(i, 25); await page.waitForTimeout(30); }
  check(await page.evaluate(() => window.__said.filter((s) => /Railway crossing/.test(s)).length) === 1, 'the crossing called once: ' + JSON.stringify(await page.evaluate(() => window.__said)));
});

